#!/usr/bin/env node
// Turns the story data into game data (task ENG-01, 12-开工规格.md sections 0 and 2):
//   1. runs check-texts.mjs and stops with exit code 1 if a strict text file has errors;
//   2. writes src/iselan/data/vocab.generated.ts (vocabulary, id types, event payload types);
//   3. writes src/iselan/data/texts.generated.ts (compiled entries of the strict text files).
//
//   node docs/story/tools/build-data.mjs           (= npm run texts)
//   node docs/story/tools/build-data.mjs --text-dir <dir>   other options go to check-texts.mjs
//
// The generated files are not committed; dev, test and build run this first.

import { spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const TOOLS = dirname(fileURLToPath(import.meta.url))
const STORY = join(TOOLS, '..')
const OUT_DIR = join(STORY, '../../src/iselan/data')
const HEADER = '// Generated by docs/story/tools/build-data.mjs (npm run texts). Do not edit.\n'

// Payload field type in events.v1.json -> TypeScript type. A value containing "|" is a union:
// for a field listed in events.fieldTypes (an id field such as towardsId: "npc|party") a part
// naming an id kind stands for that id type; every other part is a string literal. Anything
// else must be listed here so new kinds are not missed.
const FIELD_TYPES = {
  int: 'number',
  'int[]': 'readonly number[]',
  string: 'string',
  'string[]': 'readonly string[]',
  bool: 'boolean',
  region: 'RegionId',
  place: 'PlaceId',
  arc: 'ArcId',
  beat: 'BeatId',
  bellCity: 'BellCityId',
  darkLine: 'DarkLineId',
  darkLineState: 'DarkLineStateId',
  direction: 'DirectionId',
  doorOutcome: 'DoorOutcomeId',
  fact: 'FactId',
  faction: 'FactionId',
  'faction[]': 'readonly FactionId[]',
  factionState: 'FactionStateId',
  interaction: 'InteractionId',
  npc: 'NpcId',
  npcState: 'NpcStateId',
  object: 'ObjectId',
  openingHook: 'OpeningHookId',
  outcome: 'OutcomeId',
  'outcome[]': 'readonly OutcomeId[]',
  truth: 'TruthId',
}

function fieldType(raw, field, idFields) {
  if (raw.includes('|')) return raw.split('|').map((x) => (idFields[field] && FIELD_TYPES[x]) || JSON.stringify(x)).join(' | ')
  const t = FIELD_TYPES[raw]
  if (!t) throw new Error(`events.v1.json: unknown payload field type "${raw}" (add it to FIELD_TYPES)`)
  return t
}

export function generateVocab(vocab, events) {
  const types = [
    ['RegionId', 'V["regions"][number]["id"]'],
    ['PlaceId', 'V["places"][number]["id"]'],
    ['BellCityId', 'V["bellCities"][number]["id"]'],
    ['ArcId', 'V["arcs"][number]["id"]'],
    ['NpcId', 'V["npcs"][number]["id"]'],
    ['PcId', 'V["pcs"][number]["id"]'],
    ['ActorId', 'NpcId | PcId'],
    ['NpcStateId', 'ValueOf<V["npcStates"]>'],
    ['FactionId', 'V["factions"][number]["id"]'],
    ['FactionStateId', 'ValueOf<V["factionStates"]>'],
    ['DarkLineId', 'V["darkLines"][number]["id"]'],
    ['DarkLineStateId', 'ValueOf<V["darkLineStates"]>'],
    ['EvidenceId', 'ValueOf<V["darkLines"][number]["evidence"]>'],
    ['TruthId', 'V["darkLines"][number]["truthId"] | V["truthLayers"][number]["id"]'],
    ['DirectionId', 'V["directions"][number]["id"]'],
    ['OpeningHookId', 'ValueOf<V["openingHooks"]>'],
    ['BeatId', 'ValueOf<V["beats"]>'],
    ['OutcomeId', 'ValueOf<V["outcomes"]>'],
    ['DoorOutcomeId', 'ValueOf<V["doorOutcomes"]>'],
    ['ObjectId', 'V["objects"][number]["id"]'],
    ['ObjectStateId', 'ValueOf<V["objects"][number]["states"]>'],
    ['FactId', 'V["facts"][number]["id"]'],
    ['VariableId', 'ValueOf<V["variables"]>["id"]'],
    ['TagGroup', 'keyof V["tags"]'],
    ['Tag', 'V["tags"][TagGroup][number]'],
    ['IntentTag', 'V["tags"]["intent"][number]'],
    ['EmotionTag', 'V["tags"]["emotion"][number]'],
    ['InteractionId', 'V["interactions"][number]'],
    ['TextKind', 'V["textKinds"][number]'],
    ['TextRegionCode', 'keyof V["textRegions"]'],
    ['DialogueLabel', 'V["dialogueLabels"][number]'],
    ['TextPlaceholder', 'V["placeholders"][number]'],
  ]
  const payloads = events.events.map((e) => {
    const fields = Object.entries(e.payload).map(([k, v]) => `    readonly ${k}: ${fieldType(v, k, events.fieldTypes)}`).join('\n')
    return `  readonly ${e.type}: {\n${fields}\n  }`
  })
  return [
    HEADER,
    `export const VOCAB = ${JSON.stringify(vocab, null, 2)} as const\n`,
    'type V = typeof VOCAB',
    'type ValueOf<T> = T extends unknown ? T[keyof T] : never\n',
    ...types.map(([n, t]) => `export type ${n} = ${t}`),
    '',
    `export const EVENT_TYPES = ${JSON.stringify(events.events.map((e) => e.type))} as const`,
    'export type EventType = (typeof EVENT_TYPES)[number]',
    `export const EVENT_GROUPS = ${JSON.stringify(Object.fromEntries(events.events.map((e) => [e.type, e.group])), null, 2)} as const\n`,
    '/** Payload field kinds as written in events.v1.json, for runtime validation. */',
    `export const EVENT_FIELDS: Readonly<Record<EventType, Readonly<Record<string, string>>>> = ${JSON.stringify(Object.fromEntries(events.events.map((e) => [e.type, e.payload])), null, 2)}\n`,
    `export const EVENT_ID_FIELDS: Readonly<Record<string, string>> = ${JSON.stringify(events.fieldTypes, null, 2)}\n`,
    'export interface EventPayloads {',
    payloads.join('\n'),
    '}\n',
    'export type EventPayload<T extends EventType> = EventPayloads[T]\n',
  ].join('\n')
}

/** Fact ids an entry reads or writes, at any depth (conditions, effects, dialogue lines). */
function factsOf(x, out = new Set()) {
  if (Array.isArray(x)) for (const y of x) factsOf(y, out)
  else if (x && typeof x === 'object') {
    for (const [k, v] of Object.entries(x)) {
      if (k === 'fact' && typeof v === 'string') out.add(v)
      else factsOf(v, out)
    }
  }
  return out
}

/** Facts that only texts not yet in the game mention: no point offering them to the host. */
export function offstageFacts(compiled) {
  const onstage = new Set()
  const offstage = new Set()
  for (const e of compiled.entries) for (const f of factsOf(e)) (e.strict ? onstage : offstage).add(f)
  return [...offstage].filter((f) => !onstage.has(f)).sort()
}

export function generateTexts(compiled) {
  const entries = compiled.entries
    .filter((e) => e.strict)
    .map(({ strict: _strict, hasTrigger: _hasTrigger, ...rest }) => rest)
  return [
    HEADER,
    "import type { FactId } from './vocab.generated'",
    "import type { CompiledText } from './textTypes'\n",
    `export const TEXTS: readonly CompiledText[] = ${JSON.stringify(entries, null, 1)}\n`,
    '/** Facts only texts outside the game mention (regions still being written). */',
    `export const OFFSTAGE_FACTS: readonly FactId[] = ${JSON.stringify(offstageFacts(compiled))}\n`,
  ].join('\n')
}

function writeIfChanged(path, content) {
  if (existsSync(path) && readFileSync(path, 'utf8') === content) return false
  writeFileSync(path, content)
  return true
}

function main() {
  const tmp = mkdtempSync(join(tmpdir(), 'iselan-texts-'))
  try {
    const out = join(tmp, 'texts.json')
    const passThrough = process.argv.slice(2)
    const run = spawnSync(process.execPath, [join(TOOLS, 'check-texts.mjs'), '--json', out, ...passThrough], { encoding: 'utf8' })
    if (run.status !== 0) {
      process.stdout.write(run.stdout)
      process.stderr.write(run.stderr)
      console.error('\n文本检查未通过，没有生成游戏数据（规则见 docs/story/12-开工规格.md 第 3 节）。')
      process.exit(1)
    }
    const vocab = JSON.parse(readFileSync(join(STORY, 'data/vocab.v1.json'), 'utf8'))
    const events = JSON.parse(readFileSync(join(STORY, 'data/events.v1.json'), 'utf8'))
    const compiled = JSON.parse(readFileSync(out, 'utf8'))
    const written = [
      writeIfChanged(join(OUT_DIR, 'vocab.generated.ts'), generateVocab(vocab, events)) && 'vocab.generated.ts',
      writeIfChanged(join(OUT_DIR, 'texts.generated.ts'), generateTexts(compiled)) && 'texts.generated.ts',
    ].filter(Boolean)
    const strictCount = compiled.entries.filter((e) => e.strict).length
    console.log(`文本检查通过；游戏数据：${strictCount} 个条目${written.length ? `，已更新 ${written.join('、')}` : '，无变化'}。`)
  } finally {
    rmSync(tmp, { recursive: true, force: true })
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) main()
